-- ====================================================================
-- جدول فروع SA للسياحة في المملكة العربية السعودية
-- Branches Table for SA Tourism
-- ====================================================================

CREATE TABLE IF NOT EXISTS `branches` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL COMMENT 'اسم الفرع',
  `name_en` VARCHAR(255) NULL COMMENT 'اسم الفرع بالإنجليزية',
  `city` VARCHAR(100) NOT NULL COMMENT 'المدينة أو المحافظة',
  `region` VARCHAR(100) NOT NULL COMMENT 'المنطقة الإدارية',
  `address` VARCHAR(255) NULL COMMENT 'العنوان التفصيلي',
  `phone` VARCHAR(50) NULL COMMENT 'رقم الهاتف المباشر',
  `whatsapp` VARCHAR(50) NULL COMMENT 'رقم الواتساب للتواصل',
  `email` VARCHAR(100) NULL COMMENT 'البريد الإلكتروني للفرع',
  `manager_name` VARCHAR(100) NULL COMMENT 'اسم مدير الفرع أو المنسق',
  `working_hours` VARCHAR(100) NULL COMMENT 'أوقات العمل الرسمية',
  `description` TEXT NULL COMMENT 'نبذة عن دور الفرع ونطاق خدماته',
  `map_url` VARCHAR(500) NULL COMMENT 'رابط خرائط جوجل',
  `is_main` TINYINT(1) DEFAULT 0 COMMENT 'هل هو المقر الرئيسي',
  `is_active` TINYINT(1) DEFAULT 1 COMMENT 'حالة التفعيل',
  `sort_order` INT DEFAULT 0 COMMENT 'ترتيب الظهور',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_region` (`region`),
  INDEX `idx_city` (`city`),
  INDEX `idx_active_sort` (`is_active`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

